export function createOfflineQueue({
  storage,
  send,
  key = "queue:v1",
  maxAttempts = 5,
}) {
  let pending = [];

  try {
    const stored = storage.getItem(key);
    if (stored !== null) {
      const parsed = JSON.parse(stored);
      if (Array.isArray(parsed)) {
        pending = parsed;
      }
    }
  } catch {
    pending = [];
  }

  let inFlight = null;
  let runningPromise = null;

  function persist() {
    storage.setItem(key, JSON.stringify(pending));
  }

  function enqueue({ id, type, payload, dedupeKey }) {
    if (pending.some((item) => item.id === id)) {
      return;
    }

    if (dedupeKey !== undefined) {
      const existing = pending.find(
        (item) => item !== inFlight && item.dedupeKey === dedupeKey
      );

      if (existing) {
        existing.type = type;
        existing.payload = payload;
        existing.attempts = 0;
        persist();
        return;
      }
    }

    pending.push({ id, type, payload, dedupeKey, attempts: 0 });
    persist();
  }

  function flush() {
    if (runningPromise !== null) {
      return runningPromise;
    }

    let resolveFlush;
    let rejectFlush;

    const promise = new Promise((resolve, reject) => {
      resolveFlush = resolve;
      rejectFlush = reject;
    });

    // Register the promise before invoking send, including reentrant calls.
    runningPromise = promise;

    (async () => {
      const sent = [];
      const failed = [];

      try {
        while (pending.length > 0) {
          const item = pending[0];
          inFlight = item;

          let outcome = "retryable";

          try {
            const response = await send({
              id: item.id,
              type: item.type,
              payload: item.payload,
            });

            const ok = response == null ? undefined : response.ok;

            if (ok === true) {
              outcome = "success";
            } else if (ok === false && response.retryable === false) {
              outcome = "rejected";
            }
          } catch {
            // Rejections and synchronous send errors are retryable.
          }

          inFlight = null;

          if (outcome === "success") {
            pending.shift();
            persist();
            sent.push(item.id);
          } else if (outcome === "rejected") {
            pending.shift();
            persist();
            failed.push({ id: item.id, reason: "rejected" });
          } else {
            item.attempts += 1;
            persist();

            if (item.attempts >= maxAttempts) {
              pending.shift();
              persist();
              failed.push({ id: item.id, reason: "max-attempts" });
            }

            break;
          }
        }

        resolveFlush({ sent, failed, remaining: pending.length });
      } catch (error) {
        rejectFlush(error);
      } finally {
        inFlight = null;
        runningPromise = null;
      }
    })();

    return promise;
  }

  function size() {
    return pending.length;
  }

  function peek() {
    return pending.map(({ id, type, payload, dedupeKey, attempts }) => ({
      id,
      type,
      payload,
      dedupeKey,
      attempts,
    }));
  }

  return { enqueue, flush, size, peek };
}
